import{_ as d,a0 as o,w as n,s as p,ao as c,I as l,x as s,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在终端里按你的方式显示日期和时间 | LCTT x X-CMD","titleTemplate":false,"description":"在终端里按你的方式显示日期和时间 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在终端里按你的方式显示日期和时间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在终端里按你的方式显示日期和时间 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191127 Displaying dates and times your way","title":"在终端里按你的方式显示日期和时间","tag":"201911","desc":""},"relativePath":"201911/20191127 Displaying dates and times your way.md","filePath":"[post].md"}'),h={name:"201911/20191127 Displaying dates and times your way.md"};function r(u,e,g,k,b,m){const i=o("Link");return n(),p("div",null,[e[15]||(e[15]=c(`<h1 id="在终端里按你的方式显示日期和时间" tabindex="-1">在终端里按你的方式显示日期和时间 <a class="header-anchor" href="#在终端里按你的方式显示日期和时间" aria-label="Permalink to “在终端里按你的方式显示日期和时间”">​</a></h1><blockquote><p>Linux 的 date 命令提供了很多显示日期和时间的选项，要比你想的还要多。这是一些有用的选择。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201911/29/144555a8mq82mcc9cfttt9.jpg" alt=""></p><p>在 Linux 系统上，<code>date</code> 命令非常简单。你键入 <code>date</code>，日期和时间将以一种有用的方式显示。它包括星期几、日期、时间和时区：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date</span></span>
<span class="line"><span>Tue 26 Nov 2019 11:45:11 AM EST</span></span></code></pre></div><p>只要你的系统配置正确，你就会看到日期和当前时间以及时区。</p><p>但是，该命令还提供了许多选项来以不同方式显示日期和时间信息。例如，如果要显示日期以便进行排序，则可能需要使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date &quot;+%Y-%m-%d&quot;</span></span>
<span class="line"><span>2019-11-26</span></span></code></pre></div><p>在这种情况下，年、月和日按该顺序排列。请注意，我们使用大写字母 <code>Y</code> 来获得四位数的年份。如果我们使用小写的 <code>y</code>，则只会看到两位数字的年份（例如 19）。不要让这种做法使你错误地联想到如果 <code>％m</code> 给你一个数字月份，<code>％M</code> 可能会给你月份的名称。不，<code>％M</code> 将给你分钟数。要以缩写名称格式获得月份，你要使用 <code>％b</code>，而对于完全拼写的月份，则要使用 <code>％B</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date &quot;+%b %B&quot;</span></span>
<span class="line"><span>Nov November</span></span></code></pre></div><p>或者，你可能希望以这种常用格式显示日期：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date &quot;+%D&quot;</span></span>
<span class="line"><span>11/26/19</span></span></code></pre></div><p>如果你需要四位数的年份，则可以执行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date &quot;+%x&quot;</span></span>
<span class="line"><span>11/26/2019</span></span></code></pre></div><p>下面是一个可能有用的示例。假设你需要创建一个每日报告并在文件名中包含日期，则可以使用以下命令来创建文件（可能用在脚本中）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch Report-\`date &quot;+%Y-%m-%d&quot;\`</span></span></code></pre></div><p>当你列出你的报告时，它们将按日期顺序或反向日期顺序（如果你添加 <code>-r</code>）列出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -r Report*</span></span>
<span class="line"><span>Report-2019-11-26</span></span>
<span class="line"><span>Report-2019-11-25</span></span>
<span class="line"><span>Report-2019-11-22</span></span>
<span class="line"><span>Report-2019-11-21</span></span>
<span class="line"><span>Report-2019-11-20</span></span></code></pre></div><p>你还可以在日期字符串中添加其他详细信息。可用的各种选项多得令人惊讶。你可以使用 <code>date &quot;+%q&quot;</code> 来显示你所在的一年中的哪个季度，或使用类似以下命令来显示两个月前的日期：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date --date=&quot;2 months ago&quot;</span></span>
<span class="line"><span>Thu 26 Sep 2019 09:02:43 AM EDT</span></span></code></pre></div><p>是否想知道下周四的日期？你可以使用类似 <code>date --date=&quot;next thu&quot;</code> 的命令，但是要理解，对于Linux，下个周四意味着今天之后的周四。如果今天是星期三，那就是明天，而不是下周的星期四。但是，你可以像下面的第二个命令一样指定下周的星期四。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date --date=&quot;next thu&quot;</span></span>
<span class="line"><span>Thu 28 Nov 2019 12:00:00 AM EST</span></span>
<span class="line"><span>$ date --date=&quot;next week thu&quot;</span></span>
<span class="line"><span>Thu 05 Dec 2019 12:00:00 AM EST</span></span></code></pre></div><p><code>date</code> 命令的手册页列出了其所有选项。该列表多得令人难以置信，但是你可能会发现一些日期/时间显示选项非常适合你。以下是一些你可能会发现有趣的东西。</p><p>世界标准时间（UTC）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date -u</span></span>
<span class="line"><span>Tue 26 Nov 2019 01:13:59 PM UTC</span></span></code></pre></div><p>自 1970 年 1 月 1 日以来的秒数（与 Linux 系统上日期的存储方式有关）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date +%s</span></span>
<span class="line"><span>1574774137</span></span></code></pre></div><p>以下是 <code>date</code> 命令选项的完整列表。正如我所说，它比我们大多数人想象的要广泛得多。</p><ul><li><code>%%</code> 显示字母 ％</li><li><code>％a</code> 本地语言环境的缩写星期名称（例如，日 / Sun）</li><li><code>％A</code> 本地语言环境的完整星期名称（例如，星期日 / Sunday）</li><li><code>％b</code> 本地语言环境的缩写月份名称（例如 一 / Jan）</li><li><code>％B</code> 本地语言环境的完整月份名称（例如，一月 / January）</li><li><code>％c</code> 本地语言环境的日期和时间（例如 2005年3月3日 星期四 23:05:25 / Thu Mar 3 23:05:25 2005）</li><li><code>％C</code> 世纪；类似于 <code>％Y</code>，但省略了后两位数字（例如，20）</li><li><code>%d</code> 月份的天（例如，01）</li><li><code>％D</code> 日期；与 <code>％m/％d/％y</code> 相同</li><li><code>％e</code> 月份的天，填充前缀空格；与 <code>％_d</code> 相同</li><li><code>％F</code> 完整日期；与 <code>％Y-％m-％d</code> 相同</li><li><code>％g</code> ISO 周号的年份的后两位数字（请参见 <code>％G</code>）</li><li><code>%G</code> ISO 周号的年份（请参阅 <code>％V</code>）；通常仅配合 <code>％V</code> 使用</li><li><code>％h</code> 与 <code>％b</code> 相同</li><li><code>％H</code> 24 小时制的小时（00..23）</li><li><code>％I</code> 12 小时制的小时（01..12）</li><li><code>%j</code> 一年的天（001..366）</li><li><code>％k</code> 24 小时制的小时，填充前缀空格（ 0..23）；与 <code>％_H</code> 相同</li><li><code>％l</code> 12 小时制的小时，填充前缀空格（ 1..12）；与 <code>％_I</code> 相同</li><li><code>％m</code> 月份（01..12）</li><li><code>％M</code> 分钟（00..59）</li><li><code>％n</code> 换行符</li><li><code>％N</code> 纳秒（000000000..999999999）</li><li><code>%p</code> 本地语言环境中等同于 AM 或 PM 的字符串；如果未知，则为空白</li><li><code>％P</code> 像 <code>％p</code>，但使用小写</li><li><code>％q</code> 季度（1..4）</li><li><code>％r</code> 本地语言环境的 12 小时制时间（例如，晚上 11:11:04 / 11:11:04 PM）</li><li><code>％R</code> 24 小时制的小时和分钟；与 <code>％H:％M</code> 相同</li><li><code>%s</code> 自 1970-01-01 00:00:00 UTC 以来的秒数</li><li><code>％S</code> 秒（00..60）</li><li><code>％t</code> 制表符</li><li><code>％T</code> 时间；与 <code>％H:％M:％S</code> 相同</li><li><code>％u</code> 星期（1..7）；1 是星期一</li><li><code>％U</code> 年的周号，以星期日为一周的第一天，从 00 开始（00..53）</li><li><code>％V</code> ISO 周号，以星期一为一周的第一天，从 01 开始（01..53）</li><li><code>％w</code> 星期（0..6）；0 是星期日</li><li><code>％W</code> 年的周号，星期一为一周的第一天，从 00 开始（00..53）</li><li><code>％x</code> 本地语言环境的日期表示形式（例如，1999年12月31日 / 12/31/99）</li><li><code>％X</code> 本地语言环境的时间表示形式（例如，23:13:48）</li><li><code>％y</code> 年的最后两位数字（00..99）</li><li><code>％Y</code> 年份</li><li><code>％z</code> +hhmm 格式的数字时区（例如，-0400）</li><li><code>％:z</code> +hh:mm 格式的数字时区（例如，-04:00）</li><li><code>％::z</code> +hh:mm:ss 格式的数字时区（例如，-04:00:00）</li><li><code>％:::z</code> 数字时区，<code>:</code> 指明精度（例如，-04, +05:30）</li><li><code>％Z</code> 字母时区缩写（例如，EDT）</li></ul><hr>`,30)),l("p",null,[e[1]||(e[1]=s("via: ",-1)),a(i,{href:"https://www.networkworld.com/article/3481602/displaying-dates-and-times-your-way-with-linux.html"},{default:t(()=>[...e[0]||(e[0]=[s("https://www.networkworld.com/article/3481602/displaying-dates-and-times-your-way-with-linux.html",-1)])]),_:1})]),l("p",null,[e[6]||(e[6]=s("作者：",-1)),a(i,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...e[2]||(e[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),l("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const x=d(h,[["render",r]]);export{C as __pageData,x as default};
